import React from 'react';
import { Card, CardContent, Chip, Grid, Typography } from '@mui/material';
import { readinessChipColor, readinessLabel } from '../../constants/complianceHub';

interface ComplianceReadinessGridProps {
  items: { key: string; label: string; status?: string }[];
  /** Tighter spacing when nested inside a section card. */
  compact?: boolean;
}

const ComplianceReadinessGrid: React.FC<ComplianceReadinessGridProps> = ({ items, compact = false }) => (
  <Grid container spacing={compact ? 1.5 : 2} sx={{ mb: compact ? 0 : 3 }}>
    {items.map((item) => (
      <Grid item xs={12} sm={6} md={4} key={item.key}>
        <Card variant="outlined">
          <CardContent>
            <Typography variant="subtitle2" color="text.secondary" gutterBottom>
              {item.label}
            </Typography>
            <Chip
              size="small"
              label={readinessLabel(item.status)}
              color={readinessChipColor(item.status)}
            />
          </CardContent>
        </Card>
      </Grid>
    ))}
  </Grid>
);

export default ComplianceReadinessGrid;
